collections.push({"id": "forest-floor", "group": "landscape", "cover": "forest-8", "photos": ["forest-16", "forest-10", "forest-5", "forest-6", "ferns", "forest-11", "forest-12", "forest-13", "forest-8", "forest-9"], "names": {"uk": "На лісовій підстилці", "ru": "На лесной подстилке", "en": "On the forest floor", "de": "Auf dem Waldboden", "pl": "Na leśnej ściółce"}, "descriptions": {"uk": "Сонячні плями між стовбурами ведуть погляд униз — до папороті, розтрісканої кори, моху й грибів серед опалого листя. Ці кадри про ліс, який відкривається в дрібних деталях.", "ru": "Солнечные пятна между стволами ведут взгляд вниз — к папоротникам, растрескавшейся коре, мху и грибам среди опавшей листвы. Эти кадры о лесе, который открывается в небольших деталях.", "en": "Patches of sunlight between the trunks draw the eye down to ferns, cracked bark, moss and mushrooms among fallen leaves. Photographs of a forest revealed through small details.", "de": "Sonnenflecken zwischen den Stämmen lenken den Blick nach unten: zu Farnen, rissiger Rinde, Moos und Pilzen im gefallenen Laub. Diese Fotografien eines Waldes, der sich in kleinen Details erschließt.", "pl": "Plamy słońca między pniami kierują wzrok w dół — ku paprociom, spękanej korze, mchowi i grzybom wśród opadłych liści. Fotografie lasu, który odsłania się w drobnych szczegółach."}});
