function filter(group,scroll=false){active=group;activeCollection=null;const url=new URL(location.href);url.searchParams.delete('series');history.replaceState(null,'',url);renderGallery();if(!scroll)document.querySelector('#filters [aria-pressed="true"]').focus();if(scroll)$('#photographs').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}

function selectCollection(id){activeCollection=id;if(id)active=collections.find(c=>c.id===id).group;const url=new URL(location.href);if(id)url.searchParams.set('series',id);else url.searchParams.delete('series');history.replaceState(null,'',url);renderGallery();document.querySelector('#collection-nav button')?.focus();}
function renderCollections(){const nav=$('#collection-nav');nav.replaceChildren();const choices=collections.filter(c=>c.group===active);nav.hidden=choices.length===0;if(nav.hidden)return;if(activeCollection){const c=choices.find(c=>c.id===activeCollection),back=document.createElement('button');back.className='button';back.textContent=groupTitle(active);back.onclick=()=>selectCollection(null);const description=document.createElement('p');description.textContent=c.descriptions[lang];nav.append(back,description);return;}choices.forEach(c=>{const button=document.createElement('button');button.className='collection-card';const image=document.createElement('img');image.src=`assets/photography/${c.cover}-720.webp`;image.alt='';image.loading='lazy';const text=document.createElement('span'),name=document.createElement('strong'),detail=document.createElement('span'),count=document.createElement('small');name.textContent=c.names[lang];detail.textContent=c.descriptions[lang];count.textContent=String(c.photos.length).padStart(2,'0')+' / '+groupTitle(active);text.append(name,detail,count);button.append(image,text);button.onclick=()=>selectCollection(c.id);nav.append(button)});}

function renderGallery(){const c=COPY[lang];$('#gallery-title').textContent=activeCollection?collections.find(c=>c.id===activeCollection).names[lang]:(active==='all'?c.all:groupTitle(active));renderCollections();$('#count').textContent=String(visible().length).padStart(2,'0')+' / PHOTOGRAPHY';$('#filters').replaceChildren();['all',...groups].forEach(g=>{const b=document.createElement('button');b.textContent=g==='all'?c.all:groupTitle(g);b.setAttribute('aria-pressed',String(active===g));b.onclick=()=>filter(g);$('#filters').append(b)});$('#gallery').replaceChildren();visible().forEach((p,i)=>{const f=document.createElement('figure');f.className='photo-card';const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',title(p));const img=document.createElement('img');img.src=asset(p,720);img.srcset=`${asset(p,720)} 720w, ${asset(p,1440)} 1440w`;img.sizes=i%7===0?'90vw':'(max-width:700px) 88vw, 45vw';img.width=p.width;img.height=p.height;img.alt=title(p);img.loading='lazy';img.decoding='async';b.append(img);b.insertAdjacentHTML('beforeend',expand);b.onclick=()=>openViewer(i,b);const cap=document.createElement('figcaption');const t=document.createElement('span');t.textContent=title(p);const s=document.createElement('small');s.textContent=groupTitle(p.group);cap.append(t,s);f.append(b,cap);$('#gallery').append(f)});}
function render(){const c=COPY[lang];document.documentElement.lang=lang;document.title=({uk:'Фотографія',ru:'Фотография',en:'Photography',de:'Fotografie',pl:'Fotografia'})[lang]+' — Krystyna Mishchenko';document.querySelectorAll('[data-t]').forEach(e=>{const v=c[e.dataset.t];if(['headline','contactTitle'].includes(e.dataset.t))e.innerHTML=v;else e.textContent=v});$('#language').value=lang;document.querySelectorAll('a[href="index.html"], #hub-return').forEach(a=>{a.href='concepts.html?lang='+lang});renderHero();$('#series-grid').replaceChildren();groups.forEach((g,i)=>{const p=photos.find(p=>p.id===covers[i]),b=document.createElement('button');b.className='series-card';const img=document.createElement('img');img.src=asset(p,720);img.alt=groupTitle(g);img.loading='lazy';img.width=p.width;img.height=p.height;const s=document.createElement('span');s.className='series-name';s.textContent=groupTitle(g);const count=document.createElement('small');count.textContent=String(photos.filter(p=>p.group===g).length).padStart(2,'0');s.append(count);b.append(img,s);b.onclick=()=>filter(g,true);$('#series-grid').append(b)});const selected=$('#shoot-type').selectedIndex;$('#shoot-type').replaceChildren(...c.types.map(t=>new Option(t,t)));$('#shoot-type').selectedIndex=Math.max(0,selected);['close','prev','next'].forEach(id=>$('#'+id).setAttribute('aria-label',c[id]));$('#filters').setAttribute('aria-label',c.series);$('#viewer').setAttribute('aria-label',c.all);renderGallery();themeLabel();if($('#viewer').open)showImage();}
